#define IRIS_MVPL_DITHER1_DITHERCONTROL_blue_range_select(x) (((uint32_t)(((uint32_t)(x)) << IRIS_MVPL_DITHER1_DITHERCONTROL_blue_range_select_SHIFT)) & IRIS_MVPL_DITHER1_DITHERCONTROL_blue_range_select_MASK)
