#define USB3_HCIVERSION_CAPLENGTH_HCIVERSION(x)  (((uint32_t)(((uint32_t)(x)) << USB3_HCIVERSION_CAPLENGTH_HCIVERSION_SHIFT)) & USB3_HCIVERSION_CAPLENGTH_HCIVERSION_MASK)
